//! Bounded enumeration and census of finite posets.
//!
//! All posets on the labelled set `{0, .., n-1}` are generated by adding one
//! element at a time: the last element `k` is given a down-set `D` and an
//! up-set `U` of the order on `{0, .., k-1}` with `D` and `U` disjoint and
//! every element of `D` below every element of `U`. Every labelled poset on
//! `k + 1` elements arises from exactly one poset on `k` elements and exactly
//! one such pair, so the recursion enumerates each labelled poset once and
//! never visits the `2^(n(n-1))` relations on `n` elements.
//!
//! The work still grows very fast (130023 labelled posets on 6 elements,
//! 6129859 on 7), so every entry point takes an explicit bound and refuses
//! larger sizes with [`PosetError::SizeBound`]:
//!
//! - [`MAX_CENSUS_SIZE`] for enumeration and the unlabelled census;
//! - [`MAX_CANONICAL_SIZE`] for canonical forms, isomorphism tests and
//!   automorphism counts, which try every relabelling that respects the
//!   invariant `(number of predecessors, number of successors)`.
//!
//! Known counts, used as tests rather than assumed: labelled posets
//! `1, 1, 3, 19, 219, 4231, 130023` and unlabelled posets
//! `1, 1, 2, 5, 16, 63, 318` for `n = 0..=6`.
//!
//! AuthorityEffect: None.

use crate::finite_poset::{FinitePoset, PosetError};
use std::collections::BTreeMap;

/// Largest `n` for which all posets on `n` elements are enumerated.
pub const MAX_CENSUS_SIZE: usize = 6;

/// Largest `n` for which canonical forms and automorphism groups are computed.
pub const MAX_CANONICAL_SIZE: usize = 8;

/// An isomorphism class of posets on `n` elements.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PosetClass {
    /// The poset in canonical labelling.
    pub representative: FinitePoset,
    /// The number of order automorphisms of the class.
    pub automorphisms: u64,
    /// How many labelled posets on `{0, .., n-1}` belong to the class.
    /// By the orbit-stabilizer theorem this is `n! / automorphisms`.
    pub labelled_copies: u64,
}

/// An order on `{0, .., k-1}` as predecessor and successor masks.
#[derive(Clone)]
struct Partial {
    down: Vec<u16>,
    up: Vec<u16>,
}

fn mask_bits(mask: u16) -> impl Iterator<Item = usize> {
    (0..16usize).filter(move |&i| (mask >> i) & 1 == 1)
}

/// Visit every labelled poset on `n` elements; `n` is at most
/// [`MAX_CENSUS_SIZE`], which keeps every mask inside 16 bits.
fn enumerate_labelled(
    n: usize,
    visit: &mut dyn FnMut(&Partial) -> Result<(), PosetError>,
) -> Result<(), PosetError> {
    let mut partial = Partial {
        down: Vec::with_capacity(n),
        up: Vec::with_capacity(n),
    };
    extend(0, n, &mut partial, visit)
}

fn extend(
    k: usize,
    n: usize,
    partial: &mut Partial,
    visit: &mut dyn FnMut(&Partial) -> Result<(), PosetError>,
) -> Result<(), PosetError> {
    if k == n {
        return visit(partial);
    }
    // `k < n <= MAX_CENSUS_SIZE`, so this shift stays far inside 16 bits.
    let full: u16 = (1u16 << k) - 1;
    for down_set in 0..=full {
        if mask_bits(down_set).any(|x| partial.down[x] & !down_set != 0) {
            continue;
        }
        // Everything in the new down-set must lie below everything in the new up-set.
        let mut allowed = full & !down_set;
        for x in mask_bits(down_set) {
            allowed &= partial.up[x];
        }
        for up_set in 0..=full {
            if up_set & !allowed != 0 {
                continue;
            }
            if mask_bits(up_set).any(|y| partial.up[y] & !up_set != 0) {
                continue;
            }
            apply_and_recurse(k, n, down_set, up_set, partial, visit)?;
        }
    }
    Ok(())
}

fn apply_and_recurse(
    k: usize,
    n: usize,
    down_set: u16,
    up_set: u16,
    partial: &mut Partial,
    visit: &mut dyn FnMut(&Partial) -> Result<(), PosetError>,
) -> Result<(), PosetError> {
    let bit = 1u16 << k;
    partial.down.push(down_set);
    partial.up.push(up_set);
    for x in mask_bits(down_set) {
        partial.up[x] |= bit;
    }
    for y in mask_bits(up_set) {
        partial.down[y] |= bit;
    }
    let outcome = extend(k + 1, n, partial, visit);
    for x in mask_bits(down_set) {
        partial.up[x] &= !bit;
    }
    for y in mask_bits(up_set) {
        partial.down[y] &= !bit;
    }
    partial.down.pop();
    partial.up.pop();
    outcome
}

fn check_census_size(n: usize) -> Result<(), PosetError> {
    if n > MAX_CENSUS_SIZE {
        Err(PosetError::SizeBound {
            operation: "poset census",
            requested: n,
            limit: MAX_CENSUS_SIZE,
        })
    } else {
        Ok(())
    }
}

fn check_canonical_size(operation: &'static str, n: usize) -> Result<(), PosetError> {
    if n > MAX_CANONICAL_SIZE {
        Err(PosetError::SizeBound {
            operation,
            requested: n,
            limit: MAX_CANONICAL_SIZE,
        })
    } else {
        Ok(())
    }
}

fn relations_of(partial: &Partial) -> Vec<(usize, usize)> {
    let mut relations = Vec::new();
    for (u, &above) in partial.up.iter().enumerate() {
        for v in mask_bits(above) {
            relations.push((u, v));
        }
    }
    relations
}

/// The number of posets on the labelled set `{0, .., n-1}`, counted without
/// building them. Refused above [`MAX_CENSUS_SIZE`].
pub fn labelled_poset_count(n: usize) -> Result<u64, PosetError> {
    check_census_size(n)?;
    let mut count = 0u64;
    enumerate_labelled(n, &mut |_| {
        count += 1;
        Ok(())
    })?;
    Ok(count)
}

/// Every poset on `{0, .., n-1}`, each built through the validating
/// constructor, in the deterministic order of the recursion. Refused above
/// [`MAX_CENSUS_SIZE`].
pub fn labelled_posets(n: usize) -> Result<Vec<FinitePoset>, PosetError> {
    check_census_size(n)?;
    let mut posets = Vec::new();
    enumerate_labelled(n, &mut |partial| {
        posets.push(FinitePoset::new(n, relations_of(partial))?);
        Ok(())
    })?;
    Ok(posets)
}

/// `(number of predecessors, number of successors)` of every element: an
/// isomorphism invariant, used to restrict the relabellings that are tried.
fn invariants(poset: &FinitePoset) -> Vec<(usize, usize)> {
    (0..poset.size())
        .map(|u| {
            (
                poset.predecessors(u).map_or(0, |p| p.len()),
                poset.successors(u).map_or(0, |s| s.len()),
            )
        })
        .collect()
}

/// Advance `items` to the next permutation in lexicographic order.
fn next_permutation(items: &mut [usize]) -> bool {
    if items.len() < 2 {
        return false;
    }
    let mut i = items.len() - 1;
    while i > 0 && items[i - 1] >= items[i] {
        i -= 1;
    }
    if i == 0 {
        return false;
    }
    let mut j = items.len() - 1;
    while items[j] <= items[i - 1] {
        j -= 1;
    }
    items.swap(i - 1, j);
    items[i..].reverse();
    true
}

/// Elements grouped by invariant, blocks ordered by invariant.
fn invariant_blocks(poset: &FinitePoset) -> Vec<Vec<usize>> {
    let invariants = invariants(poset);
    let mut by_invariant: BTreeMap<(usize, usize), Vec<usize>> = BTreeMap::new();
    for (element, invariant) in invariants.iter().enumerate() {
        by_invariant.entry(*invariant).or_default().push(element);
    }
    by_invariant.into_values().collect()
}

fn best_relabelling(
    relations: &[(usize, usize)],
    blocks: &[Vec<usize>],
    block_index: usize,
    offset: usize,
    label: &mut [usize],
    best: &mut Option<Vec<(usize, usize)>>,
) {
    if block_index == blocks.len() {
        let mut mapped: Vec<(usize, usize)> = relations
            .iter()
            .map(|&(u, v)| (label[u], label[v]))
            .collect();
        mapped.sort_unstable();
        if best.as_ref().is_none_or(|current| mapped < *current) {
            *best = Some(mapped);
        }
        return;
    }
    let block = &blocks[block_index];
    let mut arrangement: Vec<usize> = block.clone();
    loop {
        for (slot, &element) in arrangement.iter().enumerate() {
            label[element] = offset + slot;
        }
        best_relabelling(
            relations,
            blocks,
            block_index + 1,
            offset + block.len(),
            label,
            best,
        );
        if !next_permutation(&mut arrangement) {
            break;
        }
    }
}

/// The lexicographically least sorted relation list over all relabellings
/// that keep elements with smaller `(predecessors, successors)` first.
///
/// Two posets are isomorphic exactly when their canonical relations are
/// equal: an isomorphism preserves the invariant, so both posets admit the
/// same set of relabelled relation lists, and equal lists are equal posets.
///
/// Refused above [`MAX_CANONICAL_SIZE`] elements.
pub fn canonical_relations(poset: &FinitePoset) -> Result<Vec<(usize, usize)>, PosetError> {
    check_canonical_size("canonical form", poset.size())?;
    let relations = poset.strict_relations();
    let blocks = invariant_blocks(poset);
    let mut label = vec![0usize; poset.size()];
    let mut best = None;
    best_relabelling(&relations, &blocks, 0, 0, &mut label, &mut best);
    Ok(best.unwrap_or_default())
}

/// Whether the two posets are isomorphic. Refused above
/// [`MAX_CANONICAL_SIZE`] elements.
pub fn are_isomorphic(a: &FinitePoset, b: &FinitePoset) -> Result<bool, PosetError> {
    check_canonical_size("isomorphism test", a.size().max(b.size()))?;
    if a.size() != b.size() || a.relation_count() != b.relation_count() {
        return Ok(false);
    }
    Ok(canonical_relations(a)? == canonical_relations(b)?)
}

/// The number of order automorphisms (permutations `s` with `u < v` exactly
/// when `s(u) < s(v)`), by backtracking with early consistency checks.
/// Refused above [`MAX_CANONICAL_SIZE`] elements.
pub fn automorphism_count(poset: &FinitePoset) -> Result<u64, PosetError> {
    check_canonical_size("automorphism count", poset.size())?;
    let invariants = invariants(poset);
    let mut image = vec![usize::MAX; poset.size()];
    let mut used = vec![false; poset.size()];
    Ok(count_automorphisms(
        poset,
        &invariants,
        0,
        &mut image,
        &mut used,
    ))
}

fn count_automorphisms(
    poset: &FinitePoset,
    invariants: &[(usize, usize)],
    next: usize,
    image: &mut [usize],
    used: &mut [bool],
) -> u64 {
    if next == poset.size() {
        return 1;
    }
    let mut total = 0;
    for candidate in 0..poset.size() {
        if used[candidate] || invariants[candidate] != invariants[next] {
            continue;
        }
        let consistent = (0..next).all(|earlier| {
            let below = poset.less(earlier, next).unwrap_or(false);
            let above = poset.less(next, earlier).unwrap_or(false);
            poset.less(image[earlier], candidate).unwrap_or(false) == below
                && poset.less(candidate, image[earlier]).unwrap_or(false) == above
        });
        if !consistent {
            continue;
        }
        image[next] = candidate;
        used[candidate] = true;
        total += count_automorphisms(poset, invariants, next + 1, image, used);
        used[candidate] = false;
        image[next] = usize::MAX;
    }
    total
}

/// The isomorphism classes of posets on `n` elements, in the order of their
/// canonical relation lists, each with its automorphism count and the number
/// of labelled posets it contains. Refused above [`MAX_CENSUS_SIZE`].
pub fn unlabelled_census(n: usize) -> Result<Vec<PosetClass>, PosetError> {
    check_census_size(n)?;
    let mut labelled_copies: BTreeMap<Vec<(usize, usize)>, u64> = BTreeMap::new();
    enumerate_labelled(n, &mut |partial| {
        let poset = FinitePoset::new(n, relations_of(partial))?;
        *labelled_copies
            .entry(canonical_relations(&poset)?)
            .or_insert(0) += 1;
        Ok(())
    })?;
    labelled_copies
        .into_iter()
        .map(|(relations, copies)| {
            let representative = FinitePoset::new(n, relations)?;
            Ok(PosetClass {
                automorphisms: automorphism_count(&representative)?,
                representative,
                labelled_copies: copies,
            })
        })
        .collect()
}

