        assert!(zero_cap.is_err());
        assert_eq!(BoundaryError321c9962::EmptyAdmission.violated_invariant(), "admitted_items >= 1");
        assert_eq!(BoundaryError321c9962::CapacityZero.violated_invariant(), "capacity_bound >= 1");
